from pathlib import Path
import re

# Collect all SNTLQ markers from all section files
found = {}
for sf in sorted((Path('output') / 'sections').glob('*.md')):
    content = sf.read_text()
    markers = re.findall(r'SNTLQ\d+', content)
    for m in markers:
        if m in found:
            print(f'DUPLICATE: {m} found in {found[m]} and {sf.name}')
        else:
            found[m] = sf.name

# Check we have all 15 markers (SNTLQ001-SNTLQ015)
for i in range(1, 16):
    marker = f'SNTLQ{i:03d}'
    if marker not in found:
        print(f'MISSING: {marker}')
    else:
        print(f'{marker} -> {found[marker]}')

print(f'\nTotal unique markers: {len(found)}')
"
